def roman_to_int(s):
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_map[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def word_wrap(text, width):
    if not text:
        return []

    words = text.split()
    lines = []
    current_line = words[0]

    for word in words[1:]:
        if len(current_line) + len(word) + 1 <= width:
            current_line += ' ' + word
        else:
            lines.append(current_line)
            current_line = word

    lines.append(current_line)

    # Split words longer than width
    new_lines = []
    for line in lines:
        words = line.split()
        new_line = []
        for word in words:
            if len(word) > width:
                new_line.extend([word[i:i+width] for i in range(0, len(word), width)])
            else:
                new_line.append(word)
        new_lines.append(' '.join(new_line))

    return new_lines
